"""命令行入口：python -m forms submit --form f.json --answers a.json --db data.db
              python -m forms show --db data.db --id 1"""

import argparse
import json
import math
import sqlite3
import sys
from decimal import Decimal
from urllib.parse import quote

VALID_TYPES = ("text", "number", "select")


def _emit(payload, code):
    json.dump(payload, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    sys.exit(code)


def _invalid_input():
    _emit({"error": "invalid_input"}, 2)


def _storage_error():
    _emit({"error": "storage_error"}, 2)


def _reject_constant(value):
    raise ValueError("invalid JSON constant: %s" % value)


def _load_json(path):
    try:
        with open(path, "r", encoding="utf-8") as fh:
            text = fh.read()
    except (OSError, UnicodeError):
        _invalid_input()
    try:
        return text, json.loads(text, parse_constant=_reject_constant)
    except ValueError:
        _invalid_input()


def _check_form(form):
    """校验表单结构，不合法时直接以 invalid_input 退出，否则返回 fields 列表。"""
    if not isinstance(form, dict):
        _invalid_input()
    fields = form.get("fields")
    if not isinstance(fields, list) or not fields:
        _invalid_input()
    seen = set()
    for field in fields:
        if not isinstance(field, dict):
            _invalid_input()
        fid = field.get("id")
        if not isinstance(fid, str) or not fid or fid in seen:
            _invalid_input()
        seen.add(fid)
        ftype = field.get("type")
        if ftype not in VALID_TYPES:
            _invalid_input()
        if not isinstance(field.get("required", False), bool):
            _invalid_input()
        if "maxLength" in field:
            if ftype != "text":
                _invalid_input()
            max_length = field["maxLength"]
            if isinstance(max_length, bool) or not isinstance(max_length, int) or max_length < 0:
                _invalid_input()
        if "minLength" in field:
            if ftype != "text":
                _invalid_input()
            min_length = field["minLength"]
            if isinstance(min_length, bool) or not isinstance(min_length, int) or min_length < 0:
                _invalid_input()
        if "minLength" in field and "maxLength" in field and min_length > max_length:
            _invalid_input()
        if "minimum" in field:
            if ftype != "number":
                _invalid_input()
            minimum = field["minimum"]
            # bool 是 int 的子类，须先排除；仅接受有限的 int/float
            # （1e400 会解码为 inf，同样拒绝）。
            if isinstance(minimum, bool) or not isinstance(minimum, (int, float)):
                _invalid_input()
            if isinstance(minimum, float) and not math.isfinite(minimum):
                _invalid_input()
        if "maximum" in field:
            if ftype != "number":
                _invalid_input()
            maximum = field["maximum"]
            if isinstance(maximum, bool) or not isinstance(maximum, (int, float)):
                _invalid_input()
            if isinstance(maximum, float) and not math.isfinite(maximum):
                _invalid_input()
        if "minimum" in field and "maximum" in field:
            # 两侧均为 int 时按任意精度整数比较；否则用 Decimal 精确比较，
            # 避免大整数转 float 舍入后误判区间为空或非空。
            if isinstance(minimum, int) and isinstance(maximum, int):
                inverted = minimum > maximum
            else:
                inverted = Decimal(minimum) > Decimal(maximum)
            if inverted:
                _invalid_input()
        if ftype == "select":
            options = field.get("options")
            if (
                not isinstance(options, list)
                or not options
                or any(not isinstance(o, str) for o in options)
                or len(set(options)) != len(options)
            ):
                _invalid_input()
    return fields


def _below_minimum(value, minimum):
    # 两侧均为 int 时直接按任意精度整数比较；否则用 Decimal 精确比较
    # float 的实际二进制值，避免大整数/小数舍入误判。
    if isinstance(value, int) and isinstance(minimum, int):
        return value < minimum
    return Decimal(value) < Decimal(minimum)


def _above_maximum(value, maximum):
    if isinstance(value, int) and isinstance(maximum, int):
        return value > maximum
    return Decimal(value) > Decimal(maximum)


def _validate(fields, answers):
    """汇总全部字段错误，每字段一个码，必填判断优先。"""
    errors = {}
    by_id = {f["id"]: f for f in fields}
    for key in answers:
        if key not in by_id:
            errors[key] = "unknown_field"
    for field in fields:
        fid = field["id"]
        missing = fid not in answers
        value = answers.get(fid)
        if field.get("required", False) and (missing or value is None or value == ""):
            errors[fid] = "required"
            continue
        if missing or value is None:
            continue
        ftype = field["type"]
        if ftype == "text":
            if not isinstance(value, str):
                errors[fid] = "type"
            elif "maxLength" in field and len(value) > field["maxLength"]:
                errors[fid] = "max_length"
            elif "minLength" in field and len(value) < field["minLength"]:
                errors[fid] = "min_length"
        elif ftype == "number":
            # int 为任意精度，必然有限；仅 float 需排除 inf/nan（如 1e400 解析为 inf）
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                errors[fid] = "type"
            elif isinstance(value, float) and not math.isfinite(value):
                errors[fid] = "type"
            elif "minimum" in field and _below_minimum(value, field["minimum"]):
                errors[fid] = "min_value"
            elif "maximum" in field and _above_maximum(value, field["maximum"]):
                errors[fid] = "max_value"
        elif ftype == "select":
            if not isinstance(value, str):
                errors[fid] = "type"
            elif value not in field["options"]:
                errors[fid] = "choice"
    return errors


def _save(db_path, form_text, answers_text):
    try:
        conn = sqlite3.connect(db_path)
        try:
            conn.execute(
                "CREATE TABLE IF NOT EXISTS submissions ("
                "id INTEGER PRIMARY KEY AUTOINCREMENT, "
                "form TEXT NOT NULL, "
                "answers TEXT NOT NULL)"
            )
            cur = conn.execute(
                "INSERT INTO submissions (form, answers) VALUES (?, ?)",
                (form_text, answers_text),
            )
            conn.commit()
            return cur.lastrowid
        finally:
            conn.close()
    except sqlite3.Error:
        _storage_error()


def _submit(args):
    form_text, form = _load_json(args.form)
    answers_text, answers = _load_json(args.answers)
    fields = _check_form(form)
    if not isinstance(answers, dict):
        _invalid_input()
    errors = _validate(fields, answers)
    if errors:
        _emit({"valid": False, "errors": errors}, 1)
    submission_id = _save(args.db, form_text, answers_text)
    _emit({"valid": True, "errors": {}, "submissionId": submission_id}, 0)


_MAX_ID = 9223372036854775807


def _parse_id(raw):
    """只接受 ASCII 数字十进制整数（允许前导零），范围 1..2**63-1。"""
    if not raw or any(ch not in "0123456789" for ch in raw):
        _invalid_input()
    value = int(raw)
    if value < 1 or value > _MAX_ID:
        _invalid_input()
    return value


def _decode_object(text):
    """解码保存的 JSON 原文，必须是合法 JSON 对象，否则报存储错误。"""
    try:
        value = json.loads(text, parse_constant=_reject_constant)
    except (ValueError, TypeError):
        _storage_error()
    if not isinstance(value, dict):
        _storage_error()
    return value


def _show(args):
    submission_id = _parse_id(args.id)
    try:
        # 只读模式打开：数据库不存在或不可读时直接报错，绝不创建文件
        uri = "file:%s?mode=ro" % quote(args.db, safe="/")
        conn = sqlite3.connect(uri, uri=True)
        try:
            row = conn.execute(
                "SELECT id, form, answers FROM submissions WHERE id = ?",
                (submission_id,),
            ).fetchone()
        finally:
            conn.close()
    except sqlite3.Error:
        _storage_error()
    if row is None:
        _emit({"error": "not_found"}, 1)
    form = _decode_object(row[1])
    answers = _decode_object(row[2])
    _emit({"submissionId": row[0], "form": form, "answers": answers}, 0)


def main(argv=None):
    parser = argparse.ArgumentParser(prog="forms")
    subparsers = parser.add_subparsers(dest="command", required=True)
    submit = subparsers.add_parser("submit", help="校验并保存一次答卷提交")
    submit.add_argument("--form", required=True, help="表单 JSON 文件路径")
    submit.add_argument("--answers", required=True, help="答卷 JSON 文件路径")
    submit.add_argument("--db", required=True, help="SQLite 数据库路径")
    show = subparsers.add_parser("show", help="按编号读取一份历史答卷")
    show.add_argument("--db", required=True, help="SQLite 数据库路径")
    show.add_argument("--id", required=True, help="提交编号（十进制正整数）")
    args = parser.parse_args(argv)
    if args.command == "submit":
        _submit(args)
    elif args.command == "show":
        _show(args)


if __name__ == "__main__":
    main()

"""text 字段 minLength 约束的回归测试。

只通过公开入口 ``python -m forms submit`` 执行：合成 JSON 写入临时目录，
检查退出码与 stdout 解析后的 JSON，并用标准库 sqlite3 核对落库结果。
不导入 forms 包内的任何内部函数，不读取或修改既有数据库。
"""

import json
import os
import sqlite3
import subprocess
import sys
import tempfile
import unittest

REPO_ROOT = os.path.dirname(os.path.abspath(__file__))


def _text_field(min_length=None, max_length=None, required=False):
    field = {"id": "note", "type": "text"}
    if required:
        field["required"] = True
    if min_length is not None:
        field["minLength"] = min_length
    if max_length is not None:
        field["maxLength"] = max_length
    return field


class MinLengthTests(unittest.TestCase):
    def setUp(self):
        self._tmp = tempfile.TemporaryDirectory()
        self.tmp = self._tmp.name

    def tearDown(self):
        self._tmp.cleanup()

    # -- 辅助 ------------------------------------------------------------

    def _run_raw(self, form_text, answers_text, db_path=None):
        """以给定原文写文件并执行提交。

        每次使用全新的子目录；db_path 为 None 时数据库也位于该子目录
        （尚不存在），传入既有路径则可验证失败不影响已有库。
        """
        run_dir = tempfile.mkdtemp(dir=self.tmp)
        form_path = os.path.join(run_dir, "form.json")
        answers_path = os.path.join(run_dir, "answers.json")
        if db_path is None:
            db_path = os.path.join(run_dir, "data.db")
        with open(form_path, "w", encoding="utf-8") as fh:
            fh.write(form_text)
        with open(answers_path, "w", encoding="utf-8") as fh:
            fh.write(answers_text)
        env = os.environ.copy()
        env["PYTHONIOENCODING"] = "utf-8"
        env["PYTHONUTF8"] = "1"
        proc = subprocess.run(
            [
                sys.executable,
                "-m",
                "forms",
                "submit",
                "--form",
                form_path,
                "--answers",
                answers_path,
                "--db",
                db_path,
            ],
            cwd=REPO_ROOT,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            env=env,
        )
        return proc, db_path, form_text, answers_text

    def _run(self, form, answers, db_path=None):
        return self._run_raw(
            json.dumps(form, ensure_ascii=False),
            json.dumps(answers, ensure_ascii=False),
            db_path=db_path,
        )

    def _payload(self, proc):
        return json.loads(proc.stdout.decode("utf-8"))

    def _assert_ok(self, result):
        """退出码 0、valid 为 true、errors 为空，且原文按新行落库。"""
        proc, db_path, form_text, answers_text = result
        self.assertEqual(proc.returncode, 0, proc.stderr.decode("utf-8"))
        payload = self._payload(proc)
        self.assertTrue(payload["valid"])
        self.assertEqual(payload["errors"], {})
        submission_id = payload["submissionId"]
        self.assertIsInstance(submission_id, int)
        self.assertTrue(os.path.exists(db_path))
        with sqlite3.connect(db_path) as conn:
            rows = conn.execute(
                "SELECT id, form, answers FROM submissions ORDER BY id"
            ).fetchall()
        self.assertTrue(rows)
        self.assertEqual(rows[-1][0], submission_id)
        self.assertEqual(rows[-1][1], form_text)
        self.assertEqual(rows[-1][2], answers_text)
        return payload, rows

    def _assert_validation_failed(self, result, expected_errors):
        """退出码 1、错误码精确匹配、无 submissionId，且不创建数据库。"""
        proc, db_path, _, _ = result
        self.assertEqual(proc.returncode, 1, proc.stderr.decode("utf-8"))
        self.assertEqual(
            self._payload(proc),
            {"valid": False, "errors": expected_errors},
        )
        self.assertFalse(os.path.exists(db_path))

    def _assert_invalid_input(self, result):
        """退出码 2、输出恰为 invalid_input，且不创建数据库。"""
        proc, db_path, _, _ = result
        self.assertEqual(proc.returncode, 2, proc.stderr.decode("utf-8"))
        self.assertEqual(self._payload(proc), {"error": "invalid_input"})
        self.assertFalse(os.path.exists(db_path))

    # -- 边界值：零下限、恰好达到、差一个码点 ------------------------------

    def test_zero_limit_empty_string_passes(self):
        result = self._run(
            {"fields": [_text_field(min_length=0)]}, {"note": ""}
        )
        self._assert_ok(result)

    def test_exactly_at_limit_passes(self):
        # “中🙂”为两个 Unicode 码点（UTF-8 下共 7 字节）。
        result = self._run(
            {"fields": [_text_field(min_length=2)]}, {"note": "中🙂"}
        )
        self._assert_ok(result)

    def test_one_code_point_under_limit_fails(self):
        result = self._run(
            {"fields": [_text_field(min_length=2)]}, {"note": "中"}
        )
        self._assert_validation_failed(result, {"note": "min_length"})

    # -- 计量单位：解码后的码点，而非转义文本、UTF-8 字节或 UTF-16 单元 --

    def test_length_counts_decoded_code_points(self):
        # 每项：答卷 JSON 原文片段（刻意保留转义写法）、下限、是否应通过。
        cases = [
            # "\n" 在 JSON 源文本中占两字符，解码后换行只算 1 个码点。
            (r'{"note": "a\nb"}', 3, True),
            (r'{"note": "a\nb"}', 4, False),
            # 代理对转义源文本很长，解码为 🙂 一个码点（4 个 UTF-8 字节、
            # 2 个 UTF-16 单元）。
            (r'{"note": "🙂"}', 1, True),
            (r'{"note": "🙂"}', 2, False),
            # 空格按 1 个码点计量：中 + 空格 + 文 = 3。
            ('{"note": "中 文"}', 3, True),
            ('{"note": "中 文"}', 4, False),
            # 中文 3 字节、emoji 4 字节，合计 7 字节但只有 2 个码点。
            ('{"note": "中🙂"}', 2, True),
            # 空字符串为 0 个码点，下限 1 应失败。
            ('{"note": ""}', 1, False),
        ]
        for raw_answers, limit, should_pass in cases:
            with self.subTest(raw=raw_answers, limit=limit):
                form_text = json.dumps(
                    {"fields": [_text_field(min_length=limit)]},
                    ensure_ascii=False,
                )
                result = self._run_raw(form_text, raw_answers)
                if should_pass:
                    self._assert_ok(result)
                else:
                    self._assert_validation_failed(
                        result, {"note": "min_length"}
                    )

    def test_empty_string_without_min_length_submits(self):
        result = self._run({"fields": [_text_field()]}, {"note": ""})
        self._assert_ok(result)

    # -- 与必填、类型判断的交互 ------------------------------------------

    def test_optional_missing_and_null_pass_at_any_limit(self):
        form = {"fields": [_text_field(min_length=2)]}
        for answers in ({}, {"note": None}):
            with self.subTest(answers=answers):
                self._assert_ok(self._run(form, answers))

    def test_optional_empty_string_limit_zero_passes_limit_one_fails(self):
        self._assert_ok(
            self._run({"fields": [_text_field(min_length=0)]}, {"note": ""})
        )
        self._assert_validation_failed(
            self._run({"fields": [_text_field(min_length=1)]}, {"note": ""}),
            {"note": "min_length"},
        )

    def test_required_takes_precedence_over_length(self):
        # 必填问题对缺失、null、空字符串仍报 required，而非 min_length。
        form = {"fields": [_text_field(min_length=2, required=True)]}
        for answers in ({}, {"note": None}, {"note": ""}):
            with self.subTest(answers=answers):
                self._assert_validation_failed(
                    self._run(form, answers), {"note": "required"}
                )

    def test_required_non_string_reports_type_not_min_length(self):
        form = {"fields": [_text_field(min_length=2, required=True)]}
        for bad_value in (123, True, ["x"], {"a": 1}):
            with self.subTest(bad_value=bad_value):
                self._assert_validation_failed(
                    self._run(form, {"note": bad_value}),
                    {"note": "type"},
                )

    def test_optional_non_string_reports_type_not_min_length(self):
        form = {"fields": [_text_field(min_length=2)]}
        for bad_value in (123, False, ["x"], {"a": 1}):
            with self.subTest(bad_value=bad_value):
                self._assert_validation_failed(
                    self._run(form, {"note": bad_value}),
                    {"note": "type"},
                )

    def test_required_short_string_still_reports_min_length(self):
        form = {"fields": [_text_field(min_length=2, required=True)]}
        result = self._run(form, {"note": "中"})
        self._assert_validation_failed(result, {"note": "min_length"})

    # -- 与 maxLength 同时配置 ---------------------------------------------

    def test_min_and_max_together(self):
        # 下限 2、上限 4：恰好等于任一端通过，越界各报对应错误码。
        form = {"fields": [_text_field(min_length=2, max_length=4)]}
        for ok_text in ("中🙂", "中🙂AB"):
            with self.subTest(ok_text=ok_text):
                self._assert_ok(self._run(form, {"note": ok_text}))
        self._assert_validation_failed(
            self._run(form, {"note": "中"}), {"note": "min_length"}
        )
        self._assert_validation_failed(
            self._run(form, {"note": "中🙂ABC"}), {"note": "max_length"}
        )

    def test_equal_min_and_max_accepts_exact_length_only(self):
        # 长度同时等于上下限的文本通过，每字段只返回一个错误码。
        form = {"fields": [_text_field(min_length=2, max_length=2)]}
        self._assert_ok(self._run(form, {"note": "中🙂"}))
        self._assert_validation_failed(
            self._run(form, {"note": "中"}), {"note": "min_length"}
        )
        self._assert_validation_failed(
            self._run(form, {"note": "中🙂A"}), {"note": "max_length"}
        )

    # -- 非法 minLength 定义 ---------------------------------------------

    def test_invalid_min_length_values_reject_form(self):
        # 其余配置与答卷均合法，失败原因只能来自 minLength 取值。
        for bad in (-1, True, "2", None, 2.5):
            with self.subTest(bad=bad):
                form = {"fields": [{"id": "note", "type": "text",
                                    "minLength": bad}]}
                self._assert_invalid_input(self._run(form, {}))

    def test_min_length_on_number_or_select_rejects_form(self):
        number_form = {
            "fields": [{"id": "n", "type": "number", "minLength": 5}]
        }
        select_form = {
            "fields": [
                {"id": "s", "type": "select",
                 "options": ["A"], "minLength": 5}
            ]
        }
        self._assert_invalid_input(self._run(number_form, {}))
        self._assert_invalid_input(self._run(select_form, {}))

    def test_min_length_greater_than_max_length_rejects_form(self):
        form = {
            "fields": [{"id": "note", "type": "text",
                        "minLength": 3, "maxLength": 2}]
        }
        self._assert_invalid_input(self._run(form, {"note": "中🙂"}))

    def test_invalid_form_wins_over_answer_errors(self):
        # 即使答卷同时存在字段错误，非法表单仍退出 2 且只报 invalid_input。
        form = {
            "fields": [
                {"id": "note", "type": "text", "minLength": -1},
                {"id": "req", "type": "text", "required": True},
            ]
        }
        # req 缺失（required）、extra 未定义（unknown_field）。
        result = self._run(form, {"note": "中", "extra": "x"})
        proc, db_path, _, _ = result
        self.assertEqual(proc.returncode, 2, proc.stderr.decode("utf-8"))
        self.assertEqual(self._payload(proc), {"error": "invalid_input"})
        self.assertFalse(os.path.exists(db_path))

    # -- 成功落库：原文保留、已有记录不动 ---------------------------------

    def test_success_preserves_raw_text_and_existing_rows(self):
        form = {"fields": [_text_field(min_length=2)]}
        form_text = json.dumps(form, ensure_ascii=False)

        # 先写入一条种子记录。
        seeded = self._run(form, {"note": "中🙂"})
        _, db_path, _, _ = seeded
        _, seeded_rows = self._assert_ok(seeded)

        # 含中文、空格与换行的原文（换行刻意保留 \n 转义写法）。
        raw_answers = '{"note": "中 文\\n🙂"}'
        result = self._run_raw(form_text, raw_answers, db_path=db_path)
        proc, _, _, _ = result
        self.assertEqual(proc.returncode, 0, proc.stderr.decode("utf-8"))
        payload = self._payload(proc)
        self.assertTrue(payload["valid"])
        self.assertEqual(payload["errors"], {})
        submission_id = payload["submissionId"]
        self.assertIsInstance(submission_id, int)

        with sqlite3.connect(db_path) as conn:
            rows = conn.execute(
                "SELECT id, form, answers FROM submissions ORDER BY id"
            ).fetchall()
        # 已有记录保持原样，新记录追加在后。
        self.assertEqual(rows[: len(seeded_rows)], seeded_rows)
        self.assertEqual(len(rows), len(seeded_rows) + 1)
        new_row = rows[-1]
        self.assertEqual(new_row[0], submission_id)
        # 原文未被裁剪或重写：与写入文件的字节内容完全一致。
        self.assertEqual(new_row[1], form_text)
        self.assertEqual(new_row[2], raw_answers)

    # -- 失败不影响既有库 -------------------------------------------------

    def test_failure_leaves_existing_database_unchanged(self):
        form = {"fields": [_text_field(min_length=2)]}
        seeded = self._run(form, {"note": "中🙂"})
        _, db_path, _, _ = seeded
        _, seeded_rows = self._assert_ok(seeded)

